create or replace function public.finance_voucher_post_v500(p_tenant_id uuid,p_location_id uuid,p_voucher_type text,p_voucher_date date,p_amount numeric,p_debit_account_id uuid,p_credit_account_id uuid,p_party_type text default null,p_party_id uuid default null,p_payment_method text default null,p_reference_number text default null,p_narration text default '') returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare v_id uuid:=gen_random_uuid();v_no text;v_journal uuid;v_lines jsonb;v_bad text;begin perform private.v500_accounting_access(p_tenant_id,true);if p_voucher_type not in('payment','receipt','contra') then raise exception 'Invalid voucher type';end if;if coalesce(p_amount,0)<=0 then raise exception 'Voucher amount must be greater than zero';end if;if p_debit_account_id=p_credit_account_id then raise exception 'Debit and credit accounts must be different';end if;select string_agg(coalesce(system_key,code),', ') into v_bad from public.accounting_accounts where tenant_id=p_tenant_id and id in(p_debit_account_id,p_credit_account_id) and system_key in('accounts_receivable','accounts_payable','inventory_asset','input_gst','output_gst','loan_receivable','loan_payable');if v_bad is not null then raise exception 'Use the source transaction/Payment Center for protected control account(s): %',v_bad;end if;if (select count(*) from public.accounting_accounts where id in(p_debit_account_id,p_credit_account_id) and tenant_id=p_tenant_id and active)<>2 then raise exception 'Invalid accounting account';end if;if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'operate');end if;v_no:=upper(substr(p_voucher_type,1,3))||'-'||lpad(nextval('public.finance_voucher_number_seq_v500')::text,8,'0');v_lines:=jsonb_build_array(jsonb_build_object('account_id',p_debit_account_id,'debit',round(p_amount,2),'credit',0,'party_type',p_party_type,'party_id',p_party_id,'description',coalesce(nullif(trim(p_narration),''),v_no)),jsonb_build_object('account_id',p_credit_account_id,'debit',0,'credit',round(p_amount,2),'party_type',p_party_type,'party_id',p_party_id,'description',coalesce(nullif(trim(p_narration),''),v_no)));v_journal:=private.v4_journal_create(p_tenant_id,p_location_id,coalesce(p_voucher_date,current_date),coalesce(nullif(trim(p_narration),''),initcap(p_voucher_type)||' voucher '||v_no),'finance_voucher_v500',v_id,v_no,v_lines);insert into public.finance_vouchers_v500(id,tenant_id,location_id,voucher_number,voucher_type,voucher_date,amount,debit_account_id,credit_account_id,party_type,party_id,payment_method,reference_number,narration,journal_id,created_by) values(v_id,p_tenant_id,p_location_id,v_no,p_voucher_type,coalesce(p_voucher_date,current_date),round(p_amount,2),p_debit_account_id,p_credit_account_id,nullif(trim(coalesce(p_party_type,'')),''),p_party_id,nullif(trim(coalesce(p_payment_method,'')),''),nullif(trim(coalesce(p_reference_number,'')),''),coalesce(nullif(trim(p_narration),''),initcap(p_voucher_type)||' voucher'),v_journal,auth.uid());return jsonb_build_object('voucher_id',v_id,'voucher_number',v_no,'journal_id',v_journal);end $$; grant execute on function public.finance_voucher_post_v500(uuid,uuid,text,date,numeric,uuid,uuid,text,uuid,text,text,text) to authenticated;
create or replace function public.journal_reverse_v500(p_tenant_id uuid,p_journal_id uuid,p_reason text) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$declare j public.journal_entries%rowtype;x record;v_lines jsonb:='[]'::jsonb;v_new uuid;begin perform private.v500_accounting_access(p_tenant_id,true);if trim(coalesce(p_reason,''))='' then raise exception 'Reversal reason is required';end if;select * into j from public.journal_entries where id=p_journal_id and tenant_id=p_tenant_id for update;if not found then raise exception 'Journal not found';end if;if j.status<>'posted' then raise exception 'Only posted journals can be reversed';end if;if coalesce(j.source_type,'manual') not in('manual','finance_voucher_v500','opening_balance_v500') then raise exception 'Operational journal % must be reversed from its source transaction, not Journal Center',coalesce(j.source_type,'unknown');end if;perform private.v500_assert_posting_period_open(p_tenant_id,current_date);for x in select * from public.journal_lines where journal_entry_id=j.id order by id loop v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',x.account_id,'debit',x.credit,'credit',x.debit,'party_type',x.party_type,'party_id',x.party_id,'description','Reversal: '||coalesce(x.description,j.description)));end loop;update public.journal_entries set status='reversed' where id=j.id;v_new:=private.v4_journal_create(p_tenant_id,j.location_id,current_date,'Reversal of '||j.entry_number||' • '||trim(p_reason),'journal_reversal_v500',j.id,j.entry_number,v_lines);update public.journal_entries set reversal_of=j.id where id=v_new;update public.finance_vouchers_v500 set status='reversed',reversal_journal_id=v_new,reversed_by=auth.uid(),reversed_at=now() where tenant_id=p_tenant_id and journal_id=j.id;update public.opening_balance_batches_v500 set status='reversed' where tenant_id=p_tenant_id and journal_id=j.id;return v_new;end $$; grant execute on function public.journal_reverse_v500(uuid,uuid,text) to authenticated;
create or replace function public.bank_statement_match_v500(p_tenant_id uuid,p_line_id uuid,p_journal_id uuid) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$declare s public.bank_statement_lines_v500%rowtype;v_account uuid;v_net numeric;v_expected numeric;begin perform private.v500_accounting_access(p_tenant_id,true);select * into s from public.bank_statement_lines_v500 where id=p_line_id and tenant_id=p_tenant_id and status='unmatched' for update;if not found then raise exception 'Unmatched bank statement line not found';end if;select accounting_account_id into v_account from public.bank_accounts_v500 where id=s.bank_account_id and tenant_id=p_tenant_id and active;if v_account is null then raise exception 'Active bank account not found';end if;if not exists(select 1 from public.journal_entries where id=p_journal_id and tenant_id=p_tenant_id and status='posted') then raise exception 'Posted journal not found';end if;select round(coalesce(sum(l.debit-l.credit),0),2) into v_net from public.journal_lines l where l.journal_entry_id=p_journal_id and l.account_id=v_account;v_expected:=case when s.direction='credit' then round(s.amount,2) else -round(s.amount,2) end;if v_net<>v_expected then raise exception 'Journal bank movement % does not match statement % %',v_net,s.direction,s.amount;end if;update public.bank_statement_lines_v500 set matched_journal_id=p_journal_id,status='matched',matched_by=auth.uid(),matched_at=now() where id=s.id;end $$; grant execute on function public.bank_statement_match_v500(uuid,uuid,uuid) to authenticated;;
